/**
 * Settings → Send feedback: a note in the learner's own words, with context
 * that names nobody. The context is the app's version, the screen the note
 * was opened from (its first part only, so no id rides along), the
 * interface language, the notebook's two language codes and when it was
 * written. Never a word, a meaning or an address: the server takes the
 * account from the session.
 *
 * Online, the note goes at once so the learner hears at once if it could
 * not; offline (or when the server cannot be reached) it waits in the
 * outbox like any other write and the sync worker sends it with the same
 * key, so it is stored once.
 */
import { me } from '@/api/endpoints.js';
import { ApiError } from '@/api/errors.js';
import { newIdempotencyKey } from '@/api/client.js';
import type { ApiFeedbackContext, ApiFeedbackInput } from '@/api/types.js';
import { getActiveNotebook } from '@/db/repo.js';
import { db, type LexpadDb } from '@/db/schema.js';
import { getLocale } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import { syncSoon } from '@/sync/store.js';

/**
 * The longest note, in characters: the API contract's FeedbackInput.body
 * (the server refuses longer rather than cutting it).
 */
export const FEEDBACK_MAX_CHARS = 2000;

// The shapes the server accepts for each context field (app/feedback in the
// API). A value that does not fit is left out here, so an odd build number
// can never cost somebody their note.
const VERSION = /^[0-9A-Za-z][0-9A-Za-z.+_-]{0,31}$/;
const SCREEN = /^\/[0-9A-Za-z_.-]{0,63}$/;
const LANG = /^[a-z]{2,3}(-[0-9A-Za-z]{2,8})?$/;

/** The first part of a path, or undefined: `/words/01J…` becomes `/words`. */
export function screenOf(path: string | null | undefined): string | undefined {
  if (typeof path !== 'string' || !path.startsWith('/')) return undefined;
  const first = `/${path.split(/[/?#]/)[1] ?? ''}`;
  return SCREEN.test(first) ? first : undefined;
}

/** The non-personal context attached to a note. */
export async function feedbackContext(
  from: string | undefined,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<ApiFeedbackContext> {
  const context: ApiFeedbackContext = { writtenAt: now.toISOString() };
  const version = platform.env.appVersion;
  if (VERSION.test(version)) context.appVersion = version;
  const screen = screenOf(from);
  if (screen !== undefined) context.screen = screen;
  const locale = getLocale();
  if (LANG.test(locale)) context.uiLanguage = locale;
  const notebook = await getActiveNotebook(database);
  if (notebook !== undefined) {
    if (LANG.test(notebook.targetLang)) context.targetLang = notebook.targetLang;
    if (LANG.test(notebook.meaningLang)) context.meaningLang = notebook.meaningLang;
  }
  return context;
}

/** The note as it will be sent, or undefined when there is nothing to send. */
export function cleanNote(body: string): string | undefined {
  const clean = body.trim();
  if (clean === '' || [...clean].length > FEEDBACK_MAX_CHARS) return undefined;
  return clean;
}

/** Whether a failure means "not now" rather than "not this note". */
function notReachable(error: unknown): boolean {
  return error instanceof ApiError && (error.kind === 'offline' || error.kind === 'server' || error.busy);
}

async function enqueue(input: ApiFeedbackInput, key: string, database: LexpadDb): Promise<void> {
  await database.outbox.add({
    clientId: key,
    entity: 'feedback',
    entityId: key,
    op: 'upsert',
    payload: input,
    clientTs: new Date().toISOString(),
    attempts: 0,
  });
}

/**
 * Sends a note, or queues it when the server cannot be reached. Answers
 * whether it went now or is waiting. A refusal (too long, too many today)
 * is thrown as the ApiError the server sent.
 */
export async function sendFeedback(
  body: string,
  context: ApiFeedbackContext,
  database: LexpadDb = db,
): Promise<'sent' | 'queued'> {
  const clean = cleanNote(body);
  if (clean === undefined) throw new Error('empty or too long');
  const input: ApiFeedbackInput = { body: clean, context };
  const key = newIdempotencyKey();
  if (platform.network.online) {
    try {
      await me.sendFeedback(input, key);
      return 'sent';
    } catch (error) {
      if (!notReachable(error)) throw error;
    }
  }
  await enqueue(input, key, database);
  void syncSoon();
  return 'queued';
}
